ALTER TABLE "quizzes" ADD CONSTRAINT "quizzes_config_check" CHECK ("quizzes"."config_version" = 1 and (("quizzes"."type" = 'classic' and "quizzes"."config" is null) or ("quizzes"."type" = 'mosaic' and "quizzes"."config" is not null and "quizzes"."config" ? 'seed' and jsonb_typeof("quizzes"."config"->'seed') = 'number' and ("quizzes"."config"->>'seed')::numeric between 0 and 4294967295 and ("quizzes"."config"->>'seed')::numeric = trunc(("quizzes"."config"->>'seed')::numeric) and "quizzes"."image_object_key" is not null and "quizzes"."attempt_limit" between 1 and 10)));